class Dsu {
    readonly int[] parent, size;
    public int Count;                                  // how many groups right now
    public Dsu(int n) {
        parent = new int[n]; size = new int[n]; Count = n;
        for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }
    }
    public int Find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];             // compression: skip one
            x = parent[x];
        }
        return x;
    }
    public bool Union(int a, int b) {
        int ra = Find(a), rb = Find(b);
        if (ra == rb) return false;                    // already together: the edge is redundant
        if (size[ra] < size[rb]) (ra, rb) = (rb, ra);  // smaller under larger
        parent[rb] = ra;
        size[ra] += size[rb];
        Count--;
        return true;
    }
}

