public int FindCircleNum(int[][] isConnected) {
    int n = isConnected.Length;
    var dsu = new Dsu(n);
    for (int i = 0; i < n; i++)
        for (int j = i + 1; j < n; j++)
            if (isConnected[i][j] == 1) dsu.Union(i, j);
    return dsu.Count;
}

public int[] FindRedundantConnection(int[][] edges) {
    var dsu = new Dsu(edges.Length + 1);        // vertices 1..n
    foreach (var e in edges)
        if (!dsu.Union(e[0], e[1])) return e;   // endpoints already connected: the edge closes a cycle
    return new int[0];
}

